            "children": [
              {
                "mode": "normal",
                "text": "// bad-analytics.ts\nimport { db } from './database';\n\n// Mengambil 1000 user beserta detail langganan (subscription) mereka secara terpisah\nexport async function getUsersWithSubscriptionNaive() {\n  // Query 1: Ambil 1000 user\n  const users = await db.query('SELECT id, name, email FROM users LIMIT 1000');\n\n  const result = [];\n  for (const user of users.rows) {\n    // Executing Query N kali (1000 kali query tambahan!)\n    const sub = await db.query('SELECT plan, status FROM subscriptions WHERE user_id = $1', [user.id]);\n    result.push({\n      ...user,\n      subscription: sub.rows[0] || null\n    });\n  }\n\n  return result;\n}",
                "type": "code-highlight",
                "style": "",
                "detail": 0,
                "format": 0,
                "version": 1
              }
            ],
            "language": "typescript",
